1	import { useState, useEffect } from "react";
2	import {
3	  useListAssets,
4	  useCreateAsset,
5	  useUpdateAsset,
6	  useDeleteAsset,
7	  useAiEnhanceAsset,
8	  useGetProject,
9	  useUpdateProject,
10	  getListAssetsQueryKey,
11	  getGetProjectQueryKey,
12	  useListEntities,
13	  type Asset,
14	  type AssetEnhanceSuggestion,
15	} from "@workspace/api-client-react";
16	import { useQueryClient } from "@tanstack/react-query";
17	import {
18	  Plus,
19	  Trash2,
20	  ImageIcon,
21	  Edit2,
22	  Sparkles,
23	  Download,
24	  Loader2,
25	  Wand2,
26	  Save,
27	  BookOpen,
28	  Layers,
29	  Square,
30	  Circle,
31	  Dice5,
32	  User,
33	  Map as MapIcon,
34	  Package,
35	  Tag,
36	  Check,
37	  X,
38	  RefreshCw,
39	} from "lucide-react";
40	import { Button } from "@/components/ui/button";
41	import { Card, CardContent } from "@/components/ui/card";
42	import { Input } from "@/components/ui/input";
43	import { Textarea } from "@/components/ui/textarea";
44	import { Label } from "@/components/ui/label";
45	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
46	import { Skeleton } from "@/components/ui/skeleton";
47	import { useToast } from "@/hooks/use-toast";
48	
49	const KINDS = ["card", "token", "board", "tile", "rulebook", "other"];
50	
51	type ComponentKind = {
52	  id: string;
53	  label: string;
54	  kind: string;
55	  icon: React.ComponentType<{ className?: string }>;
56	  promptHint: string;
57	};
58	
59	const COMPONENT_KINDS: ComponentKind[] = [
60	  { id: "card", label: "Card", kind: "card", icon: Layers, promptHint: "a single illustrated game card with title bar, art frame, and rule text area" },
61	  { id: "board", label: "Board", kind: "board", icon: Square, promptHint: "a top-down hex or grid game board with regions and resource icons" },
62	  { id: "token", label: "Token", kind: "token", icon: Circle, promptHint: "a small circular wooden or cardboard token with a single icon" },
63	  { id: "dice", label: "Dice tray", kind: "other", icon: Dice5, promptHint: "a wooden dice tray with custom-faced dice scattered inside" },
64	  { id: "character", label: "Character art", kind: "other", icon: User, promptHint: "a character portrait, three-quarter view, painted illustration" },
65	  { id: "map", label: "Map", kind: "board", icon: MapIcon, promptHint: "a stylized world map with regions and a compass rose" },
66	  { id: "box", label: "Box cover", kind: "other", icon: Package, promptHint: "a board game box cover, dramatic key art with logo space" },
67	  { id: "logo", label: "Logo", kind: "other", icon: Tag, promptHint: "a game logo / wordmark, vector style, on transparent background" },
68	];
69	
70	export function Assets({ projectId }: { projectId: number }) {
71	  const qc = useQueryClient();
72	  const { toast } = useToast();
73	  const { data: assets, isLoading } = useListAssets(projectId);
74	  const { data: project } = useGetProject(projectId);
75	  const { data: entities } = useListEntities(projectId);
76	  const createAsset = useCreateAsset();
77	  const updateAsset = useUpdateAsset();
78	  const deleteAsset = useDeleteAsset();
79	  const updateProject = useUpdateProject();
80	  const enhanceAsset = useAiEnhanceAsset();
81	
82	  const [narrative, setNarrative] = useState("");
83	  const [narrativeDirty, setNarrativeDirty] = useState(false);
84	  const [savingNarrative, setSavingNarrative] = useState(false);
85	  useEffect(() => {
86	    if (project && !narrativeDirty) setNarrative(project.narrative ?? "");
87	  }, [project, narrativeDirty]);
88	
89	  const saveNarrative = async () => {
90	    setSavingNarrative(true);
91	    try {
92	      await updateProject.mutateAsync({ projectId, data: { narrative } });
93	      qc.invalidateQueries({ queryKey: getGetProjectQueryKey(projectId) });
94	      setNarrativeDirty(false);
95	      toast({ title: "Narrative saved" });
96	    } catch (err) {
97	      toast({ title: "Save failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
98	    } finally {
99	      setSavingNarrative(false);
100	    }
101	  };
102	
103	  const [generatingTile, setGeneratingTile] = useState<string | null>(null);
104	  const [freeformPrompt, setFreeformPrompt] = useState("");
105	  const [generatingFreeform, setGeneratingFreeform] = useState(false);
106	
107	  const composedPrompt = (kind: ComponentKind, customExtra?: string): { prompt: string; tag: string; assetName: string; description: string } => {
108	    const narr = narrative.trim() || project?.description || "a tabletop game";
109	    const entityNames = (entities ?? []).slice(0, 6).map((e) => e.name).filter(Boolean);
110	    const entityLine = entityNames.length ? `Featuring entities: ${entityNames.join(", ")}.` : "";
111	    const extra = customExtra?.trim() ? ` ${customExtra.trim()}` : "";
112	    const prompt = `Design ${kind.promptHint} for a board game called "${project?.name ?? "Untitled"}". Narrative: ${narr}. ${entityLine} Style: hand-painted, rich color, professional board-game art.${extra}`;
113	    const seedWord = narr.split(/\s+/).slice(0, 4).join(" ");
114	    const assetName = `${kind.label}: ${seedWord}`.slice(0, 60);
115	    const description = `${kind.label} from narrative beat — ${narr.slice(0, 140)}`;
116	    const tag = kind.label;
117	    return { prompt, tag, assetName, description };
118	  };
119	
120	  const generateImageDirect = async (assetId: number, prompt: string): Promise<boolean> => {
121	    const base = import.meta.env.BASE_URL.replace(/\/$/, "");
122	    const res = await fetch(`${base}/api/projects/${projectId}/assets/${assetId}/generate-image`, {
123	      method: "POST",
124	      headers: { "Content-Type": "application/json" },
125	      credentials: "include",
126	      body: JSON.stringify({ prompt }),
127	    });
128	    return res.ok;
129	  };
130	
131	  const generateFromTile = async (tile: ComponentKind) => {
132	    if (!narrative.trim() && !project?.description) {
133	      toast({ title: "Add a narrative first", description: "Write a story seed above so the AI knows what to draw.", variant: "destructive" });
134	      return;
135	    }
136	    setGeneratingTile(tile.id);
137	    try {
138	      const composed = composedPrompt(tile);
139	      const created = await createAsset.mutateAsync({
140	        projectId,
141	        data: {
142	          name: composed.assetName,
143	          kind: tile.kind,
144	          description: composed.description,
145	          flavorText: composed.tag,
146	        },
147	      });
148	      qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
149	      const ok = await generateImageDirect(created.id, composed.prompt);
150	      qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
151	      if (ok) toast({ title: `${tile.label} generated` });
152	      else toast({ title: "Image generation failed", description: "Asset created without image — try regenerating.", variant: "destructive" });
153	    } catch (err) {
154	      toast({ title: "Generation failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
155	    } finally {
156	      setGeneratingTile(null);
157	    }
158	  };
159	
160	  const generateFromFreeform = async () => {
161	    const txt = freeformPrompt.trim();
162	    if (!txt) return;
163	    setGeneratingFreeform(true);
164	    try {
165	      const narr = narrative.trim() || project?.description || "";
166	      const entityNames = (entities ?? []).slice(0, 4).map((e) => e.name).filter(Boolean);
167	      const entityLine = entityNames.length ? ` Featuring: ${entityNames.join(", ")}.` : "";
168	      const fullPrompt = narr
169	        ? `${txt}. Narrative: ${narr}.${entityLine} Style: hand-painted, rich color, professional board-game art.`
170	        : txt;
171	      const created = await createAsset.mutateAsync({
172	        projectId,
173	        data: {
174	          name: txt.slice(0, 60),
175	          kind: "other",
176	          description: `Custom — ${txt}`.slice(0, 240),
177	          flavorText: "Custom",
178	        },
179	      });
180	      qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
181	      const ok = await generateImageDirect(created.id, fullPrompt);
182	      qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
183	      if (ok) {
184	        toast({ title: "Asset generated" });
185	        setFreeformPrompt("");
186	      } else {
187	        toast({ title: "Image generation failed", variant: "destructive" });
188	      }
189	    } catch (err) {
190	      toast({ title: "Generation failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
191	    } finally {
192	      setGeneratingFreeform(false);
193	    }
194	  };
195	
196	  const fetchEnhance = async (assetId: number): Promise<AssetEnhanceSuggestion> => {
197	    return enhanceAsset.mutateAsync({ projectId, assetId });
198	  };
199	
200	  const applyEnhance = async (assetId: number, fields: Partial<{ name: string; description: string; flavorText: string }>) => {
201	    if (Object.keys(fields).length === 0) return;
202	    await updateAsset.mutateAsync({ projectId, assetId, data: fields });
203	    qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
204	  };
205	
206	  const [showAdd, setShowAdd] = useState(false);
207	  const [editing, setEditing] = useState<number | null>(null);
208	  const [form, setForm] = useState({ name: "", kind: "card", description: "", flavorText: "", entityId: "" });
209	  const [generating, setGenerating] = useState<number | null>(null);
210	  const [imagePromptId, setImagePromptId] = useState<number | null>(null);
211	  const [imagePrompt, setImagePrompt] = useState("");
212	
213	  const isFormOpen = showAdd || editing !== null;
214	
215	  const refresh = () => qc.invalidateQueries({ queryKey: getListAssetsQueryKey(projectId) });
216	  const closeForm = () => {
217	    setShowAdd(false);
218	    setEditing(null);
219	    setForm({ name: "", kind: "card", description: "", flavorText: "", entityId: "" });
220	  };
221	  const openCreate = () => {
222	    setEditing(null);
223	    setForm({ name: "", kind: "card", description: "", flavorText: "", entityId: "" });
224	    setShowAdd(true);
225	  };
226	  const openEdit = (id: number) => {
227	    const a = assets?.find(x => x.id === id); if (!a) return;
228	    setShowAdd(false);
229	    setEditing(id);
230	    setForm({ name: a.name, kind: a.kind, description: a.description || "", flavorText: a.flavorText || "", entityId: a.entityId ? String(a.entityId) : "" });
231	  };
232	
233	  const submit = async (e: React.FormEvent) => {
234	    e.preventDefault(); if (!form.name.trim()) return;
235	    const data = {
236	      name: form.name, kind: form.kind, description: form.description, flavorText: form.flavorText,
237	      ...(form.entityId ? { entityId: parseInt(form.entityId) } : {}),
238	    };
239	    try {
240	      if (editing) await updateAsset.mutateAsync({ projectId, assetId: editing, data });
241	      else await createAsset.mutateAsync({ projectId, data });
242	      closeForm(); refresh();
243	    } catch { toast({ title: "Save failed", variant: "destructive" }); }
244	  };
245	
246	  const remove = async (id: number) => {
247	    try { await deleteAsset.mutateAsync({ projectId, assetId: id }); refresh(); }
248	    catch { toast({ title: "Delete failed", variant: "destructive" }); }
249	  };
250	
251	  const generateImage = async (assetId: number, prompt: string) => {
252	    setGenerating(assetId);
253	    try {
254	      const ok = await generateImageDirect(assetId, prompt);
255	      if (!ok) throw new Error("gen failed");
256	      refresh();
257	      toast({ title: "Image generated" });
258	    } catch { toast({ title: "Generation failed", variant: "destructive" }); }
259	    finally { setGenerating(null); }
260	  };
261	
262	  const openImagePrompt = (id: number) => {
263	    const a = assets?.find(x => x.id === id);
264	    setImagePrompt(a?.imagePrompt || `${a?.name} ${a?.description || ""}`.trim());
265	    setImagePromptId(id);
266	  };
267	  const closeImagePrompt = () => {
268	    setImagePromptId(null);
269	    setImagePrompt("");
270	  };
271	
272	  const downloadImage = (a: { name: string; imageDataUrl?: string | null }) => {
273	    if (!a.imageDataUrl) return;
274	    const link = document.createElement("a");
275	    link.href = a.imageDataUrl;
276	    link.download = `${a.name.replace(/[^a-z0-9]+/gi, "_")}.png`;
277	    link.click();
278	  };
279	
280	  const totalAssets = assets?.length ?? 0;
281	
282	  return (
283	    <div className="space-y-6 max-w-6xl">
284	      <div className="flex flex-wrap items-start justify-between gap-3">
285	        <div>
286	          <h2 className="text-2xl font-bold flex items-center gap-2"><ImageIcon className="h-6 w-6 text-primary" /> Asset Library</h2>
287	          <p className="text-xs text-muted-foreground mt-1">
288	            {totalAssets} {totalAssets === 1 ? "asset" : "assets"} · click <span className="text-primary font-medium">AI</span> on any card to enhance its name, description, and flavor text
289	          </p>
290	        </div>
291	        {!isFormOpen && (
292	          <Button variant="outline" onClick={openCreate} className="gap-2" data-testid="add-asset-button"><Plus className="h-4 w-4" /> Manual asset</Button>
293	        )}
294	      </div>
295	
296	      {isFormOpen && (
297	        <Card className="bg-card border-primary/40" data-testid="asset-form-panel">
298	          <CardContent className="p-4 space-y-4">
299	            <div className="flex items-center justify-between">
300	              <div className="font-semibold">{editing ? "Edit Asset" : "New Asset"}</div>
301	              <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForm}><X className="h-4 w-4" /></Button>
302	            </div>
303	            <form onSubmit={submit} className="space-y-4">
304	              <div className="grid grid-cols-2 gap-3">
305	                <div className="space-y-2 col-span-2"><Label>Name *</Label><Input value={form.name} onChange={e => setForm({...form, name: e.target.value})} required autoFocus /></div>
306	                <div className="space-y-2"><Label>Kind</Label>
307	                  <Select value={form.kind} onValueChange={v => setForm({...form, kind: v})}>
308	                    <SelectTrigger><SelectValue /></SelectTrigger>
309	                    <SelectContent>{KINDS.map(k => <SelectItem key={k} value={k}>{k}</SelectItem>)}</SelectContent>
310	                  </Select>
311	                </div>
312	                <div className="space-y-2"><Label>Linked Entity</Label>
313	                  <Select value={form.entityId || "none"} onValueChange={v => setForm({...form, entityId: v === "none" ? "" : v})}>
314	                    <SelectTrigger><SelectValue placeholder="None" /></SelectTrigger>
315	                    <SelectContent>
316	                      <SelectItem value="none">None</SelectItem>
317	                      {entities?.map(e => <SelectItem key={e.id} value={String(e.id)}>{e.name}</SelectItem>)}
318	                    </SelectContent>
319	                  </Select>
320	                </div>
321	              </div>
322	              <div className="space-y-2"><Label>Description</Label><Textarea rows={3} value={form.description} onChange={e => setForm({...form, description: e.target.value})} /></div>
323	              <div className="space-y-2"><Label>Flavor text / tag</Label><Textarea rows={2} value={form.flavorText} onChange={e => setForm({...form, flavorText: e.target.value})} /></div>
324	              <div className="flex justify-end gap-2 pt-2">
325	                <Button type="button" variant="outline" onClick={closeForm}>Cancel</Button>
326	                <Button type="submit">{editing ? "Save" : "Create"}</Button>
327	              </div>
328	            </form>
329	          </CardContent>
330	        </Card>
331	      )}
332	
333	      {imagePromptId !== null && (
334	        <Card className="bg-card border-primary/40" data-testid="image-prompt-panel">
335	          <CardContent className="p-4 space-y-4">
336	            <div className="flex items-center justify-between">
337	              <div className="font-semibold">Generate image</div>
338	              <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeImagePrompt}><X className="h-4 w-4" /></Button>
339	            </div>
340	            <div className="space-y-2">
341	              <Label>Image prompt</Label>
342	              <Textarea rows={5} value={imagePrompt} onChange={e => setImagePrompt(e.target.value)} placeholder="A fantasy card showing..." autoFocus />
343	            </div>
344	            <div className="flex justify-end gap-2">
345	              <Button variant="outline" onClick={closeImagePrompt}>Cancel</Button>
346	              <Button onClick={() => { if (imagePromptId) { generateImage(imagePromptId, imagePrompt); closeImagePrompt(); } }} disabled={!imagePrompt.trim()} className="gap-2">
347	                <Sparkles className="h-4 w-4" /> Generate
348	              </Button>
349	            </div>
350	          </CardContent>
351	        </Card>
352	      )}
353	
354	      <Card className="bg-card border-card-border">
355	        <CardContent className="p-4 space-y-3">
356	          <div className="flex items-center gap-2">
357	            <BookOpen className="h-4 w-4 text-primary" />
358	            <Label htmlFor="narrative-seed" className="font-semibold">Narrative seed</Label>
359	            <span className="text-xs text-muted-foreground">— a short story setup the AI will weave into every component.</span>
360	          </div>
361	          <Textarea
362	            id="narrative-seed"
363	            data-testid="narrative-seed"
364	            rows={3}
365	            placeholder="A storm-wracked archipelago where rival cartels of weather-shapers race to claim drifting sky-islands…"
366	            value={narrative}
367	            onChange={(e) => { setNarrative(e.target.value); setNarrativeDirty(true); }}
368	          />
369	          <div className="flex justify-end">
370	            <Button
371	              size="sm"
372	              onClick={saveNarrative}
373	              disabled={!narrativeDirty || savingNarrative}
374	              className="gap-2"
375	              data-testid="save-narrative"
376	            >
377	              {savingNarrative ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
378	              {savingNarrative ? "Saving…" : narrativeDirty ? "Save narrative" : "Saved"}
379	            </Button>
380	          </div>
381	        </CardContent>
382	      </Card>
383	
384	      <div>
385	        <h3 className="font-semibold mb-3 text-sm uppercase tracking-wider text-muted-foreground">Component types</h3>
386	        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
387	          {COMPONENT_KINDS.map((tile) => {
388	            const Icon = tile.icon;
389	            const isLoading = generatingTile === tile.id;
390	            return (
391	              <button
392	                key={tile.id}
393	                onClick={() => generateFromTile(tile)}
394	                disabled={isLoading || !!generatingTile}
395	                data-testid={`tile-${tile.id}`}
396	                className="group flex flex-col items-center justify-center gap-2 p-4 rounded-lg border border-border bg-card hover:border-primary/50 hover:bg-primary/5 transition-colors disabled:opacity-60 disabled:cursor-not-allowed"
397	              >
398	                {isLoading ? (
399	                  <Loader2 className="h-6 w-6 text-primary animate-spin" />
400	                ) : (
401	                  <Icon className="h-6 w-6 text-primary group-hover:scale-110 transition-transform" />
402	                )}
403	                <span className="text-sm font-medium">{tile.label}</span>
404	                <span className="text-[10px] text-muted-foreground line-clamp-2 text-center">{isLoading ? "Composing…" : "Click to generate"}</span>
405	              </button>
406	            );
407	          })}
408	        </div>
409	      </div>
410	
411	      <Card className="bg-card border-card-border">
412	        <CardContent className="p-4 space-y-2">
413	          <Label htmlFor="freeform-prompt" className="text-sm font-semibold flex items-center gap-2">
414	            <Wand2 className="h-3.5 w-3.5 text-primary" /> Or describe your own component
415	          </Label>
416	          <div className="flex gap-2">
417	            <Input
418	              id="freeform-prompt"
419	              data-testid="freeform-prompt"
420	              placeholder="A weathered storm-shard talisman engraved with sky-glyphs"
421	              value={freeformPrompt}
422	              onChange={(e) => setFreeformPrompt(e.target.value)}
423	              onKeyDown={(e) => { if (e.key === "Enter" && !generatingFreeform) generateFromFreeform(); }}
424	            />
425	            <Button
426	              onClick={generateFromFreeform}
427	              disabled={!freeformPrompt.trim() || generatingFreeform}
428	              data-testid="generate-freeform"
429	              className="gap-2"
430	            >
431	              {generatingFreeform ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
432	              Generate
433	            </Button>
434	          </div>
435	        </CardContent>
436	      </Card>
437	
438	      {isLoading ? (
439	        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">{[1,2,3,4,5,6].map(i => <Skeleton key={i} className="h-72" />)}</div>
440	      ) : !assets?.length ? (
441	        <div className="text-center py-12 border border-dashed border-border rounded-xl">
442	          <p className="text-muted-foreground">No mockups yet. Pick a component type above to get started.</p>
443	        </div>
444	      ) : (
445	        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
446	          {assets.map((a) => (
447	            <AssetCard
448	              key={a.id}
449	              asset={a}
450	              isGenerating={generating === a.id}
451	              onEdit={() => openEdit(a.id)}
452	              onDelete={() => remove(a.id)}
453	              onGenerateImage={() => openImagePrompt(a.id)}
454	              onDownload={() => downloadImage(a)}
455	              fetchEnhance={() => fetchEnhance(a.id)}
456	              applyEnhance={(fields) => applyEnhance(a.id, fields)}
457	            />
458	          ))}
459	        </div>
460	      )}
461	
462	    </div>
463	  );
464	}
465	
466	// ════════════════════════════════════════════════════════════════════════════
467	// AssetCard — image, action row, and inline AI Enhancement preview panel
468	// ════════════════════════════════════════════════════════════════════════════
469	function AssetCard({
470	  asset,
471	  isGenerating,
472	  onEdit,
473	  onDelete,
474	  onGenerateImage,
475	  onDownload,
476	  fetchEnhance,
477	  applyEnhance,
478	}: {
479	  asset: Asset;
480	  isGenerating: boolean;
481	  onEdit: () => void;
482	  onDelete: () => void;
483	  onGenerateImage: () => void;
484	  onDownload: () => void;
485	  fetchEnhance: () => Promise<AssetEnhanceSuggestion>;
486	  applyEnhance: (fields: Partial<{ name: string; description: string; flavorText: string }>) => Promise<void>;
487	}) {
488	  const { toast } = useToast();
489	  const [showEnhance, setShowEnhance] = useState(false);
490	  const [isEnhancing, setIsEnhancing] = useState(false);
491	  const [suggestion, setSuggestion] = useState<AssetEnhanceSuggestion | null>(null);
492	  const [picked, setPicked] = useState<{ name: boolean; description: boolean; flavorText: boolean }>({ name: true, description: true, flavorText: true });
493	  const [applying, setApplying] = useState(false);
494	  const [applied, setApplied] = useState(false);
495	
496	  const runEnhance = async () => {
497	    setIsEnhancing(true);
498	    setSuggestion(null);
499	    setApplied(false);
500	    setShowEnhance(true);
501	    try {
502	      const data = await fetchEnhance();
503	      setSuggestion(data);
504	      setPicked({
505	        name: !!data.name && data.name !== asset.name,
506	        description: !!data.description && data.description !== (asset.description ?? ""),
507	        flavorText: !!data.flavorText && data.flavorText !== (asset.flavorText ?? ""),
508	      });
509	    } catch (err) {
510	      const desc = err instanceof Error ? err.message : String(err);
511	      toast({ title: "AI enhance failed", description: desc, variant: "destructive" });
512	      setShowEnhance(false);
513	    } finally {
514	      setIsEnhancing(false);
515	    }
516	  };
517	
518	  const handleApply = async () => {
519	    if (!suggestion) return;
520	    const fields: Partial<{ name: string; description: string; flavorText: string }> = {};
521	    if (picked.name && suggestion.name) fields.name = suggestion.name;
522	    if (picked.description && suggestion.description) fields.description = suggestion.description;
523	    if (picked.flavorText && suggestion.flavorText) fields.flavorText = suggestion.flavorText;
524	    if (Object.keys(fields).length === 0) {
525	      toast({ title: "Pick at least one field to apply", variant: "destructive" });
526	      return;
527	    }
528	    setApplying(true);
529	    try {
530	      await applyEnhance(fields);
531	      setApplied(true);
532	      toast({ title: "Asset updated" });
533	      setTimeout(() => {
534	        setShowEnhance(false);
535	        setSuggestion(null);
536	        setApplied(false);
537	      }, 1200);
538	    } catch (err) {
539	      toast({ title: "Apply failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
540	    } finally {
541	      setApplying(false);
542	    }
543	  };
544	
545	  return (
546	    <Card className="bg-card border-card-border overflow-hidden flex flex-col group" data-testid={`asset-card-${asset.id}`}>
547	      <div className="aspect-square bg-muted/30 relative">
548	        {asset.imageDataUrl ? (
549	          <img src={asset.imageDataUrl} alt={asset.name} className="w-full h-full object-cover" />
550	        ) : (
551	          <div className="w-full h-full flex items-center justify-center text-muted-foreground">
552	            <ImageIcon className="h-12 w-12 opacity-30" />
553	          </div>
554	        )}
555	        <span className="absolute top-2 left-2 text-[10px] uppercase font-bold tracking-wider bg-black/60 text-white px-2 py-0.5 rounded">{asset.kind}</span>
556	        {asset.flavorText && (
557	          <span className="absolute top-2 right-2 text-[10px] uppercase font-semibold tracking-wider bg-primary/90 text-primary-foreground px-2 py-0.5 rounded">
558	            {asset.flavorText}
559	          </span>
560	        )}
561	      </div>
562	      <CardContent className="p-4 flex-1 flex flex-col">
563	        <div className="flex justify-between items-start gap-2 mb-1">
564	          <h3 className="font-semibold line-clamp-1 flex-1">{asset.name}</h3>
565	          <div className="flex gap-0.5">
566	            <Button
567	              variant="ghost"
568	              size="sm"
569	              className={`text-xs h-7 px-2 gap-1 ${showEnhance ? "text-primary bg-primary/10" : "text-muted-foreground hover:text-primary hover:bg-primary/10"}`}
570	              title="AI Enhance text"
571	              onClick={runEnhance}
572	              disabled={isEnhancing}
573	              data-testid={`enhance-asset-${asset.id}`}
574	            >
575	              {isEnhancing ? <Loader2 className="h-3 w-3 animate-spin" /> : <Wand2 className="h-3 w-3" />}
576	              AI
577	            </Button>
578	            <Button variant="ghost" size="icon" className="h-7 w-7 opacity-0 group-hover:opacity-100" onClick={onEdit} title="Edit"><Edit2 className="h-3.5 w-3.5" /></Button>
579	            <Button variant="ghost" size="icon" className="h-7 w-7 opacity-0 group-hover:opacity-100 text-destructive" onClick={onDelete} title="Delete"><Trash2 className="h-3.5 w-3.5" /></Button>
580	          </div>
581	        </div>
582	        {asset.description && <p className="text-sm text-muted-foreground line-clamp-2 mb-2">{asset.description}</p>}
583	        <div className="flex gap-2 mt-auto">
584	          <Button size="sm" variant="outline" className="flex-1 gap-1" onClick={onGenerateImage} disabled={isGenerating}>
585	            <Sparkles className="h-3.5 w-3.5" /> {isGenerating ? "Generating..." : asset.imageDataUrl ? "Regenerate" : "Generate"}
586	          </Button>
587	          {asset.imageDataUrl && <Button size="sm" variant="outline" onClick={onDownload}><Download className="h-3.5 w-3.5" /></Button>}
588	        </div>
589	      </CardContent>
590	
591	      {/* AI Enhance Panel */}
592	      {showEnhance && (
593	        <div className="border-t border-border bg-primary/5 px-4 py-3 space-y-3" data-testid={`enhance-panel-asset-${asset.id}`}>
594	          <div className="flex items-center gap-2">
595	            <Sparkles className="w-4 h-4 text-primary shrink-0" />
596	            <p className="text-sm font-semibold text-primary flex-1">AI Enhancement</p>
597	            <button
598	              onClick={() => { setShowEnhance(false); setSuggestion(null); }}
599	              className="text-muted-foreground hover:text-white transition-colors"
600	              title="Dismiss"
601	            >
602	              <X className="w-4 h-4" />
603	            </button>
604	          </div>
605	
606	          {isEnhancing && (
607	            <div className="flex items-center gap-2 text-sm text-muted-foreground py-2">
608	              <Loader2 className="w-4 h-4 animate-spin text-primary" /> Rewriting copy…
609	            </div>
610	          )}
611	
612	          {suggestion && !isEnhancing && (
613	            <div className="space-y-3">
614	              <SuggestionField
615	                label="Name"
616	                current={asset.name}
617	                proposed={suggestion.name}
618	                checked={picked.name}
619	                onToggle={() => setPicked({ ...picked, name: !picked.name })}
620	              />
621	              <SuggestionField
622	                label="Description"
623	                current={asset.description ?? ""}
624	                proposed={suggestion.description}
625	                checked={picked.description}
626	                onToggle={() => setPicked({ ...picked, description: !picked.description })}
627	              />
628	              <SuggestionField
629	                label="Flavor text"
630	                current={asset.flavorText ?? ""}
631	                proposed={suggestion.flavorText}
632	                checked={picked.flavorText}
633	                onToggle={() => setPicked({ ...picked, flavorText: !picked.flavorText })}
634	              />
635	
636	              <div className="flex items-center gap-2 pt-1 flex-wrap">
637	                <Button
638	                  size="sm"
639	                  onClick={handleApply}
640	                  disabled={applying || applied}
641	                  className="bg-primary text-primary-foreground gap-1.5"
642	                  data-testid={`apply-enhance-asset-${asset.id}`}
643	                >
644	                  {applied
645	                    ? <><Check className="w-3.5 h-3.5" /> Applied!</>
646	                    : applying
647	                    ? <><Loader2 className="w-3.5 h-3.5 animate-spin" /> Applying…</>
648	                    : <><Wand2 className="w-3.5 h-3.5" /> Apply</>}
649	                </Button>
650	                <Button
651	                  size="sm"
652	                  variant="outline"
653	                  onClick={runEnhance}
654	                  disabled={isEnhancing}
655	                  className="border-border text-muted-foreground hover:text-white gap-1.5"
656	                >
657	                  <RefreshCw className="w-3.5 h-3.5" /> Regenerate
658	                </Button>
659	                <Button
660	                  size="sm"
661	                  variant="ghost"
662	                  onClick={() => { setShowEnhance(false); setSuggestion(null); }}
663	                  className="text-muted-foreground hover:text-white ml-auto"
664	                >
665	                  Dismiss
666	                </Button>
667	              </div>
668	            </div>
669	          )}
670	        </div>
671	      )}
672	    </Card>
673	  );
674	}
675	
676	function SuggestionField({
677	  label,
678	  current,
679	  proposed,
680	  checked,
681	  onToggle,
682	}: {
683	  label: string;
684	  current: string;
685	  proposed?: string;
686	  checked: boolean;
687	  onToggle: () => void;
688	}) {
689	  if (!proposed) {
690	    return (
691	      <div className="space-y-1">
692	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
693	        <p className="text-xs text-muted-foreground italic">No change suggested.</p>
694	      </div>
695	    );
696	  }
697	  if (proposed === current) {
698	    return (
699	      <div className="space-y-1">
700	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
701	        <p className="text-xs text-muted-foreground italic">No change — AI returned the same value.</p>
702	      </div>
703	    );
704	  }
705	  return (
706	    <div className="space-y-1.5">
707	      <div className="flex items-center justify-between">
708	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
709	        <label className="flex items-center gap-1.5 text-[11px] text-muted-foreground cursor-pointer select-none">
710	          <input
711	            type="checkbox"
712	            checked={checked}
713	            onChange={onToggle}
714	            className="h-3 w-3 accent-primary"
715	          />
716	          Apply this
717	        </label>
718	      </div>
719	      {current && (
720	        <p className="text-xs text-muted-foreground/70 line-through bg-background/40 border border-border rounded px-2 py-1">
721	          {current}
722	        </p>
723	      )}
724	      <p className={`text-xs leading-relaxed bg-background/60 border rounded px-2 py-1.5 ${checked ? "text-foreground border-primary/40" : "text-muted-foreground border-border"}`}>
725	        {proposed}
726	      </p>
727	    </div>
728	  );
729	}
