881	const PROP_TYPES = ["number", "string", "boolean", "enum"] as const;
882	
883	function EntityProperties({ projectId, entityId }: { projectId: number; entityId: number }) {
884	  const queryClient = useQueryClient();
885	  const { data: properties, isLoading } = useListEntityProperties(projectId, entityId);
886	  const createProperty = useCreateEntityProperty();
887	  const updateProperty = useUpdateEntityProperty();
888	  const deleteProperty = useDeleteEntityProperty();
889	  const { toast } = useToast();
890	
891	  const [newProp, setNewProp] = useState({ name: "", dataType: "number", defaultValue: "" });
892	  const [editingId, setEditingId] = useState<number | null>(null);
893	  const [editProp, setEditProp] = useState({ name: "", dataType: "number", defaultValue: "" });
894	
895	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
896	  const refresh = () => queryClient.invalidateQueries({ queryKey: getListEntityPropertiesQueryKey(projectId, entityId) });
897	
898	  const valueToPayload = (val: string): { defaultValue?: number; textValue?: string } => {
899	    if (val === "") return { textValue: "" };
900	    const num = Number(val);
901	    if (Number.isFinite(num) && val.trim() !== "") return { defaultValue: num, textValue: "" };
902	    return { textValue: val, defaultValue: undefined };
903	  };
904	
905	  const displayValue = (p: EntityProperty): string => {
906	    if (p.defaultValue != null) return String(p.defaultValue);
907	    if (p.textValue) return p.textValue;
908	    if (p.value != null) return String(p.value);
909	    return "—";
910	  };
911	
912	  const handleAddProp = async (e: React.FormEvent) => {
913	    e.preventDefault();
914	    if (!newProp.name) return;
915	    try {
916	      await createProperty.mutateAsync({ projectId, entityId, data: { name: newProp.name, dataType: newProp.dataType, ...valueToPayload(newProp.defaultValue) } });
917	      setNewProp({ name: "", dataType: "number", defaultValue: "" });
918	      refresh();
919	    } catch (err) {
920	      toast({ title: "Could not add property", description: errMsg(err), variant: "destructive" });
921	    }
922	  };
923	
924	  const startEdit = (prop: EntityProperty) => {
925	    setEditingId(prop.id);
926	    setEditProp({ name: prop.name, dataType: prop.dataType, defaultValue: displayValue(prop) === "—" ? "" : displayValue(prop) });
927	  };
928	
929	  const saveEdit = async () => {
930	    if (!editingId) return;
931	    try {
932	      await updateProperty.mutateAsync({ projectId, entityId, propertyId: editingId, data: { name: editProp.name, dataType: editProp.dataType, ...valueToPayload(editProp.defaultValue) } });
933	      setEditingId(null); refresh();
934	    } catch (err) {
935	      toast({ title: "Could not update property", description: errMsg(err), variant: "destructive" });
936	    }
937	  };
938	
939	  const handleDelete = async (id: number) => {
